import openpyxl
wb=openpyxl.load_workbook(\"documents/bi-loss-calculation.xlsx\")
wv=openpyxl.load_workbook(\"documents/bi-loss-calculation.xlsx\",data_only=True)
for ws in wb:
  print(\"##\",ws.title,ws.dimensions)
  for row in ws.iter_rows():
    vals=[]
    for c in row:
      if c.value is not None:
        v=c.value; cv=wv[ws.title][c.coordinate].value
        s=str(v)
        if isinstance(v,str) and v.startswith(\"=\"): s+=\" -> \"+str(cv)
        vals.append(c.coordinate+\": \"+s)
    if vals: print(\" | \".join(vals))
"
